"""One-off: the claims review's corrections to the documentation and the code comments (round 11).
   python3 -I claims_fix2.py   (run once, in tests/r11)"""
def patch(path, pairs):
    s = open(path, encoding='utf-8').read()
    for a, b in pairs:
        assert s.count(a) == 1, (path, s.count(a), a[:90])
        s = s.replace(a, b)
    open(path, 'w', encoding='utf-8').write(s)
    print('ok', path)

